import java.util.ArrayList;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        List<Map.Entry<String, Integer>> cities = new ArrayList<>();
        cities.add(Map.entry("Lima", 10_700));
        cities.add(Map.entry("Cairo", 21_300));
        cities.add(Map.entry("Seoul", 9_900));
        cities.add(Map.entry("Lagos", 15_400));
        System.out.println(cities);

        int total = 0;
        Map.Entry<String, Integer> largest = cities.get(0);
        for (Map.Entry<String, Integer> city : cities) {
            total += city.getValue();
            if (city.getValue() > largest.getValue()) {
                largest = city;
            }
        }
        System.out.println("Total: " + total + " thousand");
        System.out.println("Largest: " + largest.getKey() + " with " + largest.getValue() + " thousand");
        System.out.println("As an entry: " + largest);
    }
}

