import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        int[] start = {2, 2};
        int row = start[0];
        int col = start[1];

        List<int[]> moves = new ArrayList<>();
        moves.add(new int[]{-1, 0});
        moves.add(new int[]{0, 1});
        moves.add(new int[]{0, 1});
        moves.add(new int[]{1, 0});
        moves.add(new int[]{0, -2});

        for (int[] move : moves) {
            row += move[0];
            col += move[1];
            System.out.println("Move " + Arrays.toString(move) + " -> (" + row + ", " + col + ")");
        }

        int[] end = {row, col};
        System.out.println("Back at start: " + Arrays.equals(end, start));
    }
}
